$:set -euo pipefail
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert");
const referencePath="references/instruction-wrapper-key-aliases.json";
const copyPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json";
const originalPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const lookup=JSON.parse(fs.readFileSync(referencePath,"utf8"));
const copy=JSON.parse(fs.readFileSync(copyPath,"utf8"));
const original=JSON.parse(fs.readFileSync(originalPath,"utf8"));
assert(Array.isArray(copy)&&copy[0]&&typeof copy[0]==="object"&&!Array.isArray(copy[0]));
assert(copy[0].ai===referencePath,"Unexpected aliased bootstrap pointer");
assert(lookup.alias_lookup_path===referencePath,"Unexpected self-reference");
assert(lookup.alias_to_key.ai==="alias_lookup_path","Unexpected mapping");
const prior=JSON.stringify(copy);
delete copy[0].ai;
copy[0].alias_lookup_path=referencePath;
delete lookup.alias_lookup_path;
delete lookup.alias_to_key.ai;
lookup.total_key_count_including_lookup=Object.keys(lookup.alias_to_key).length;
lookup.aliases_with_two_characters=Object.keys(lookup.alias_to_key).filter(a=>a.length===2).length;
lookup.mapping_semantics.additional_lookup_member="The outer index-zero explainer contains the literal, unaliased member name alias_lookup_path so a reader can locate the mapping before interpreting encoded key names. The lookup reference itself does not contain a self-referential location member. The bootstrap member is exempt from alias encoding.";
lookup.mapping_semantics.decoding="Read the literal alias_lookup_path from the outer index-zero explainer and load this mapping. Replace all other encoded object keys recursively using alias_to_key, leaving the unaliased bootstrap member unchanged. Delete that bootstrap member to recover the original unmodified wrapper.";
const inverses=lookup.alias_to_key;
function decode(x) {
 if(Array.isArray(x))return x.map(decode);
 if(!x||typeof x!=="object")return x;
 const result={};
 for(const [key,value] of Object.entries(x)){
   const mapped=(key==="alias_lookup_path")?key:inverses[key];
   assert(mapped,"Unknown alias or unexpected unaliased member "+key);
   assert(!Object.hasOwn(result,mapped),"Alias collision "+mapped);
   result[mapped]=decode(value);
 }
 return result;
}
const decoded=decode(copy);
assert(decoded[0].alias_lookup_path===referencePath);
delete decoded[0].alias_lookup_path;
assert.deepStrictEqual(decoded,original,"Roundtrip mismatch");
assert(Object.keys(inverses).length===103);
assert(lookup.total_key_count_including_lookup===103);
assert(lookup.aliases_with_one_character===22);
assert(lookup.aliases_with_two_characters===81);
assert(!Object.hasOwn(lookup,"alias_lookup_path"));
assert(!Object.hasOwn(inverses,"ai"));
fs.writeFileSync(referencePath,JSON.stringify(lookup,null,2)+"\n");
fs.writeFileSync(copyPath,JSON.stringify(copy)+"\n");
const check=JSON.parse(fs.readFileSync(copyPath,"utf8"));
assert(check[0].alias_lookup_path===referencePath&&!Object.hasOwn(check[0],"ai"));
console.log("BOOTSTRAP_LITERAL_KEY",Object.keys(check[0]).slice(-1)[0]);
console.log("BOOTSTRAP_REFERENCE",check[0].alias_lookup_path);
console.log("REFERENCE_SELF_PATH_REMOVED",!Object.hasOwn(lookup,"alias_lookup_path"));
console.log("ALIAS_COUNT",Object.keys(inverses).length);
console.log("RECOVERED_ORIGINAL_EXACTLY",true);
console.log("ALISED_TEMPLATE_BYTES",Buffer.byteLength(fs.readFileSync(copyPath)));
NODE
git add -- references/instruction-wrapper-key-aliases.json 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json'
git diff --cached --check
git commit -m 'Bootstrap alias lookup with readable template key and remove lookup self-path'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
